"""Render the versioned migration from the frozen workbook schema contract."""

from devtools.database_schema import BY_NAME, FOREIGN_KEYS, TABLES


def render_migration() -> str:
    statements = [
        "-- v1: workbook v7_4_9_RISK. Generated by devtools.database_migration.",
        "CREATE SCHEMA knowledge;",
        "CREATE SCHEMA runtime;",
    ]
    for table in TABLES:
        columns = [
            f'    "{name}" {kind}' + (" PRIMARY KEY" if name == table.primary_key else "")
            for name, kind in table.columns
        ]
        statements.append(
            f"CREATE TABLE {table.schema}.{table.name} (\n" + ",\n".join(columns) + "\n);"
        )
    for index, (source, column, target, key) in enumerate(FOREIGN_KEYS, 1):
        source_table, target_table = BY_NAME[source], BY_NAME[target]
        statements.append(
            f"ALTER TABLE {source_table.schema}.{source} ADD CONSTRAINT fk_{index:03d} "
            f"FOREIGN KEY ({column}) REFERENCES {target_table.schema}.{target} ({key}) "
            "DEFERRABLE INITIALLY DEFERRED;"
        )
        # Prevent expensive joins/deletes while each developer grows their runtime data.
        if column != source_table.primary_key:
            statements.append(
                f"CREATE INDEX ix_{index:03d} ON {source_table.schema}.{source} ({column});"
            )
    statements.extend(
        [
            "CREATE INDEX ix_retrieval_run ON runtime.ket_qua_truy_xuat (lan_chay_id);",
            "CREATE INDEX ix_criterion_run ON runtime.ket_qua_tieu_chi (ca_id, lan_chay_id);",
            "CREATE INDEX ix_citation_run ON runtime.phat_hien_vien_dan (ca_id, lan_chay_id);",
            "COMMENT ON SCHEMA knowledge IS "
            "'Seed knowledge, including draft and unverified records';",
            "COMMENT ON SCHEMA runtime IS "
            "'Local sample contracts and assessment runs, not legal gold';",
        ]
    )
    return "\n\n".join(statements) + "\n"
